import{t as e}from"./utils-COoNfFoj.js";var t={slug:`wesley-breed`,influencerName:`Wesley Breed`,influencerHandle:`@wesly`,influencerAvatarUrl:`${e}/wesley-breed-avatar.png`,heroDescription:`I built the ultimate resource for car enthusiasts using Perplexity Computer, aggregating dozens of local car meets into one organized calendar. I dropped the prompt I used below so you can build your own.`,assetTitle:`East Coast Car Meets Tracker`,screenshotUrl:`${e}/wesley-breed.png`,remixUrl:`https://eccm.pplx.app/#/`,promptTitle:`Try Wesley's prompt`,promptText:`Build a vintage racing-poster-styled web app cataloging verified car meets and concours in a defined region and time window. Include a monthly calendar with category toggles, event modals with maps, calendar deep-links, and primary-sourced media galleries (every image URL browser-tested before shipping), a 14-day weather widget where event rows are clickable, and a viral leaderboard tied only to verified posts from listed events. Auto-refresh on a recurring schedule that searches organizer feeds, verifies each candidate against a primary source, and appends only what's confirmed.`};export{t as default};
